  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeMessage,
 25→  ClaudeResult,
 26→  ClaudeSystemInit,
 27→  ServerMessage,
 28→  ServerMessageHistory,
 29→  ToolCallInfo,
 30→  UserQuestion,
 31→} from "@/lib/types";
 32→
 33→const WS_URL = "ws://localhost:9900/browser";
 34→
 35→/** Per-agent client state. */
 36→export interface AgentClientState {
 37→  status: AgentStatus;
 38→  messages: ChatMessage[];
 39→  /** Raw Claude NDJSON messages for debug view. */
 40→  rawMessages: ClaudeMessage[];
 41→  label: string;
 42→  tmuxSession: string | null;
 43→  createdAt: number;
 44→}
 45→
 46→/**
 47→ * Extract displayable text from a Claude assistant message.
 48→ * Content blocks may be text, tool_use, or tool_result — each is
 49→ * handled defensively since the array structure can vary.
 50→ */
 51→function extractText(msg: ClaudeAssistant): string {
 52→  const blocks = msg.message?.content;
 53→  if (!blocks || !Array.isArray(blocks)) return "";
 54→  return blocks
 55→    .map((b) => {
 56→      if (b.type === "text") return b.text;
 57→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 58→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 59→      return "";
 60→    })
 61→    .filter(Boolean)
 62→    .join("\n");
 63→}
 64→
 65→/** Module-level counter for generating unique message IDs. */
 66→let msgCounter = 0;
 67→function nextId() {
 68→  return `msg-${Date.now()}-${++msgCounter}`;
 69→}
 70→
 71→/**
 72→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 73→ * Used both for live messages and for replaying message_history.
 74→ */
 75→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 76→  if (relayMsg.type === "relay") {
 77→    const msg = relayMsg.message;
 78→
 79→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 80→      const init = msg as ClaudeSystemInit;
 81→      return {
 82→        id: nextId(),
 83→        role: "system",
 84→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 85→        timestamp: Date.now(),
 86→      };
 87→    }
 88→
 89→    if (msg.type === "assistant") {
 90→      const assistant = msg as ClaudeAssistant;
 91→      const text = extractText(assistant);
 92→      if (!text) return null;
 93→
 94→      const blocks = assistant.message?.content ?? [];
 95→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
 96→      const toolCalls: ToolCallInfo[] = blocks
 97→        .filter((b) => b.type === "tool_use")
 98→        .map((b) => ({
 99→          name: (b as { name: string }).name,
100→          toolUseId: (b as { id: string }).id,
101→        }));
102→      const isToolOnly = !hasText && toolCalls.length > 0;
103→
104→      return {
105→        id: nextId(),
106→        role: "assistant",
107→        content: text,
108→        timestamp: Date.now(),
109→        toolCalls,
110→        isToolOnly,
111→      };
112→    }
113→
114→    if (msg.type === "result") {
115→      const result = msg as ClaudeResult;
116→      const summary = result.is_error
117→        ? `Error: ${result.error}`
118→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
119→      return {
120→        id: nextId(),
121→        role: "system",
122→        content: summary,
123→        timestamp: Date.now(),
124→      };
125→    }
126→
127→    if (msg.type === "control_request") {
128→      const cr = msg as ClaudeControlRequest;
129→
130→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
131→      if (cr.request.tool_name === "AskUserQuestion") {
132→        const input = cr.request.input as { questions?: UserQuestion[] };
133→        const questions = Array.isArray(input.questions) ? input.questions : [];
134→        return {
135→          id: nextId(),
136→          role: "system",
137→          content: "Question from Claude",
138→          timestamp: Date.now(),
139→          userQuestion: {
140→            requestId: cr.request_id,
141→            questions,
142→          },
143→        };
144→      }
145→
146→      return {
147→        id: nextId(),
148→        role: "system",
149→        content: `Tool approval requested: ${cr.request.tool_name}`,
150→        timestamp: Date.now(),
151→        controlRequest: {
152→          id: cr.request_id,
153→          tool_name: cr.request.tool_name,
154→          input: cr.request.input,
155→        },
156→      };
157→    }
158→  }
159→
160→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
161→    return {
162→      id: nextId(),
163→      role: "system",
164→      content: `Error: ${relayMsg.error}`,
165→      timestamp: Date.now(),
166→    };
167→  }
168→
169→  return null;
170→}
171→
172→export function useWebSocket() {
173→  const wsRef = useRef<WebSocket | null>(null);
174→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
175→  const [connected, setConnected] = useState(false);
176→
177→  // Multi-agent state
178→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
179→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
180→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
181→
182→  // Per-agent deduplication: track count of processed messages per agent
183→  // to avoid duplicating messages already in local state during history replay.
184→  const processedCountRef = useRef<Map<string, number>>(new Map());
185→
186→  /** Immutably update a single agent's state in the Map. */
187→  const updateAgent = useCallback(
188→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
189→      setAgents((prev) => {
190→        const existing = prev.get(agentId);
191→        if (!existing) return prev;
192→        const next = new Map(prev);
193→        next.set(agentId, updater(existing));
194→        return next;
195→      });
196→    },
197→    []
198→  );
199→
200→  const connect = useCallback(() => {
201→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
202→    if (wsRef.current) {
203→      wsRef.current.close();
204→      wsRef.current = null;
205→    }
206→
207→    const ws = new WebSocket(WS_URL);
208→    wsRef.current = ws;
209→
210→    ws.onopen = () => setConnected(true);
211→
212→    ws.onclose = () => {
213→      setConnected(false);
214→      wsRef.current = null;
215→      // Reconnection guard: clear any existing timer before scheduling
216→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
217→      reconnectTimer.current = setTimeout(() => connect(), 2000);
218→    };
219→
220→    ws.onerror = () => {
221→      // onclose will fire after onerror, which triggers reconnect
222→    };
223→
224→    ws.onmessage = (event) => {
225→      let data: ServerMessage;
226→      try {
227→        data = JSON.parse(event.data as string);
228→      } catch {
229→        return;
230→      }
231→
232→      // ── message_history: replay full history from server ──
233→      if (data.type === "message_history") {
234→        const historyMsg = data as ServerMessageHistory;
235→        const agentId = historyMsg.agentId;
236→        const serverMessages = historyMsg.messages;
237→
238→        // Convert all server messages to ChatMessages + extract raw Claude messages
239→        const chatMessages: ChatMessage[] = [];
240→        const rawMessages: ClaudeMessage[] = [];
241→        for (const sm of serverMessages) {
242→          if (sm.type === "relay") {
243→            rawMessages.push(sm.message);
244→          }
245→          const cm = relayChatMessage(agentId, sm);
246→          if (cm) chatMessages.push(cm);
247→        }
248→
249→        // Skip messages already processed locally (dedup)
250→        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
251→        const newMessages = chatMessages.slice(alreadyProcessed);
252→
253→        if (newMessages.length > 0) {
254→          setAgents((prev) => {
255→            const existing = prev.get(agentId);
256→            if (!existing) {
257→              // Agent not yet in local state — create it
258→              const next = new Map(prev);
259→              next.set(agentId, {
260→                status: "idle",
261→                messages: chatMessages, // use full history for new agent
262→                rawMessages,
263→                label: "",
264→                tmuxSession: null,
265→                createdAt: 0,
266→              });
267→              return next;
268→            }
269→            // Replace messages with full server history (source of truth)
270→            const next = new Map(prev);
271→            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
272→            return next;
273→          });
274→        }
275→
276→        processedCountRef.current.set(agentId, chatMessages.length);
277→        return;
278→      }
279→
280→      // ── cli_disconnected: show system message ──
281→      if (data.type === "cli_disconnected") {
282→        updateAgent(data.agentId, (prev) => ({
283→          ...prev,
284→          status: "disconnected",
285→          messages: [
286→            ...prev.messages,
287→            {
288→              id: nextId(),
289→              role: "system",
290→              content: "CLI disconnected — attempting reconnect...",
291→              timestamp: Date.now(),
292→            },
293→          ],
294→        }));
295→        return;
296→      }
297→
298→      // ── cli_connected: show system message ──
299→      if (data.type === "cli_connected") {
300→        updateAgent(data.agentId, (prev) => ({
301→          ...prev,
302→          messages: [
303→            ...prev.messages,
304→            {
305→              id: nextId(),
306→              role: "system",
307→              content: "CLI reconnected",
308→              timestamp: Date.now(),
309→            },
310→          ],
311→        }));
312→        return;
313→      }
314→
315→      // ── agent_list: reconcile sidebar state from server ──
316→      if (data.type === "agent_list") {
317→        const serverAgents = data.agents as AgentInfo[];
318→        setAgents((prev) => {
319→          const next = new Map(prev);
320→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
321→
322→          // Update or add agents from server
323→          for (const info of serverAgents) {
324→            const existing = next.get(info.agentId);
325→            if (existing) {
326→              next.set(info.agentId, {
327→                ...existing,
328→                status: info.status,
329→                tmuxSession: info.tmuxSession,
330→                label: info.label,
331→              });
332→            } else {
333→              next.set(info.agentId, {
334→                status: info.status,
335→                messages: [],
336→                rawMessages: [],
337→                label: info.label,
338→                tmuxSession: info.tmuxSession,
339→                createdAt: info.createdAt,
340→              });
341→            }
342→          }
343→
344→          // Remove agents no longer on the server
345→          for (const id of next.keys()) {
346→            if (!serverIds.has(id)) {
347→              next.delete(id);
348→            }
349→          }
350→
351→          return next;
352→        });
353→        setAgentOrder(serverAgents.map((a) => a.agentId));
354→        return;
355→      }
356→
357→      // ── spawned: auto-select the newly created agent ──
358→      if (data.type === "spawned") {
359→        setActiveAgentId(data.agentId);
360→        return;
361→      }
362→
363→      // ── status: update a specific agent's status ──
364→      if (data.type === "status") {
365→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
366→        return;
367→      }
368→
369→      // ── error: append to agent's message list ──
370→      if (data.type === "error") {
371→        updateAgent(data.agentId, (prev) => ({
372→          ...prev,
373→          messages: [
374→            ...prev.messages,
375→            {
376→              id: nextId(),
377→              role: "system",
378→              content: `Error: ${data.error}`,
379→              timestamp: Date.now(),
380→            },
381→          ],
382→        }));
383→        // Track processed count for dedup
384→        processedCountRef.current.set(
385→          data.agentId,
386→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
387→        );
388→        return;
389→      }
390→
391→      // ── relay: append claude message to agent's history ──
392→      if (data.type === "relay") {
393→        const agentId = data.agentId;
394→        const rawMsg = data.message;
395→        const chatMsg = relayChatMessage(agentId, data);
396→
397→        updateAgent(agentId, (prev) => ({
398→          ...prev,
399→          rawMessages: [...prev.rawMessages, rawMsg],
400→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
401→        }));
402→        if (chatMsg) {
403→          // Track processed count for dedup
404→          processedCountRef.current.set(
405→            agentId,
406→            (processedCountRef.current.get(agentId) ?? 0) + 1
407→          );
408→        }
409→        return;
410→      }
411→    };
412→  }, [updateAgent]);
413→
414→  useEffect(() => {
415→    connect();
416→    return () => {
417→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
418→      wsRef.current?.close();
419→    };
420→  }, [connect]);
421→
422→  const send = useCallback((data: object) => {
423→    if (wsRef.current?.readyState === WebSocket.OPEN) {
424→      wsRef.current.send(JSON.stringify(data));
425→    }
426→  }, []);
427→
428→  const spawnAgent = useCallback(
429→    (prompt: string) => {
430→      send({ type: "spawn", prompt });
431→    },
432→    [send]
433→  );
434→
435→  const sendMessage = useCallback(
436→    (content: string) => {
437→      if (!activeAgentId) return;
438→      // Optimistically add user message to local state
439→      updateAgent(activeAgentId, (prev) => ({
440→        ...prev,
441→        messages: [
442→          ...prev.messages,
443→          {
444→            id: nextId(),
445→            role: "user",
446→            content,
447→            timestamp: Date.now(),
448→          },
449→        ],
450→      }));
451→      send({ type: "send_message", agentId: activeAgentId, content });
452→    },
453→    [send, activeAgentId, updateAgent]
454→  );
455→
456→  const respondToControl = useCallback(
457→    (requestId: string, allow: boolean) => {
458→      if (!activeAgentId) return;
459→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
460→      updateAgent(activeAgentId, (prev) => ({
461→        ...prev,
462→        messages: prev.messages.map((m) =>
463→          m.controlRequest?.id === requestId
464→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
465→            : m
466→        ),
467→      }));
468→    },
469→    [send, activeAgentId, updateAgent]
470→  );
471→
472→  /** Respond to an AskUserQuestion control request with the user's selections. */
473→  const respondToUserQuestion = useCallback(
474→    (requestId: string, answers: Record<string, string>) => {
475→      if (!activeAgentId) return;
476→      send({
477→        type: "control_response",
478→        agentId: activeAgentId,
479→        request_id: requestId,
480→        allow: true,
481→        answers,
482→      });
483→      updateAgent(activeAgentId, (prev) => ({
484→        ...prev,
485→        messages: prev.messages.map((m) =>
486→          m.userQuestion?.requestId === requestId
487→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
488→            : m
489→        ),
490→      }));
491→    },
492→    [send, activeAgentId, updateAgent]
493→  );
494→
495→  // Derived values for the active agent
496→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
497→  const activeStatus = useMemo<AgentStatus>(
498→    () => activeAgent?.status ?? "idle",
499→    [activeAgent?.status]
500→  );
501→  const activeMessages = useMemo<ChatMessage[]>(
502→    () => activeAgent?.messages ?? [],
503→    [activeAgent?.messages]
504→  );
505→  const activeRawMessages = useMemo<ClaudeMessage[]>(
506→    () => activeAgent?.rawMessages ?? [],
507→    [activeAgent?.rawMessages]
508→  );
509→
510→  return {
511→    connected,
512→    agents,
513→    agentOrder,
514→    activeAgentId,
515→    setActiveAgentId,
516→    activeStatus,
517→    activeMessages,
518→    activeRawMessages,
519→    spawnAgent,
520→    sendMessage,
521→    respondToControl,
522→    respondToUserQuestion,
523→  };
524→}
