  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { condenseMessages } from "@/lib/condense-messages";
 21→import { StatusBar } from "./status-bar";
 22→import { Message } from "./message";
 23→import { ControlRequest } from "./control-request";
 24→import { UserQuestion } from "./user-question";
 25→import { CondensedToolGroup } from "./condensed-tool-group";
 26→import { Button } from "@/components/ui/button";
 27→
 28→export function Chat({
 29→  connected,
 30→  status,
 31→  messages,
 32→  rawMessages,
 33→  onSendMessage,
 34→  onSpawnAgent,
 35→  onRespondToControl,
 36→  onRespondToUserQuestion,
 37→}: {
 38→  connected: boolean;
 39→  status: AgentStatus;
 40→  messages: ChatMessage[];
 41→  rawMessages: ClaudeMessage[];
 42→  onSendMessage: (content: string) => void;
 43→  onSpawnAgent: (prompt: string) => void;
 44→  onRespondToControl: (requestId: string, allow: boolean) => void;
 45→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 46→}) {
 47→  const [input, setInput] = useState("");
 48→  const [showRaw, setShowRaw] = useState(false);
 49→  const scrollRef = useRef<HTMLDivElement>(null);
 50→
 51→  useEffect(() => {
 52→    scrollRef.current?.scrollTo({
 53→      top: scrollRef.current.scrollHeight,
 54→      behavior: "smooth",
 55→    });
 56→  }, [messages, rawMessages, showRaw]);
 57→
 58→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 59→  const isActive = status === "connected" || status === "thinking";
 60→
 61→  function handleSubmit(e: React.FormEvent) {
 62→    e.preventDefault();
 63→    const trimmed = input.trim();
 64→    if (!trimmed) return;
 65→
 66→    if (isActive) {
 67→      onSendMessage(trimmed);
 68→    } else {
 69→      onSpawnAgent(trimmed);
 70→    }
 71→    setInput("");
 72→  }
 73→
 74→  return (
 75→    <div className="flex h-full flex-col">
 76→      <div className="relative">
 77→        <StatusBar connected={connected} status={status} />
 78→        <button
 79→          onClick={() => setShowRaw((v) => !v)}
 80→          className={`absolute right-3 top-1/2 -translate-y-1/2 rounded px-2 py-0.5 text-[10px] font-mono transition-colors ${
 81→            showRaw
 82→              ? "bg-foreground text-background"
 83→              : "bg-muted text-muted-foreground hover:bg-muted/80"
 84→          }`}
 85→        >
 86→          {showRaw ? "RAW" : "raw"}
 87→        </button>
 88→      </div>
 89→
 90→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-2">
 91→        {showRaw ? (
 92→          rawMessages.length === 0 ? (
 93→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 94→              No raw messages yet
 95→            </div>
 96→          ) : (
 97→            <div className="space-y-1">
 98→              {rawMessages.map((msg, i) => (
 99→                <RawMessage key={i} message={msg} index={i} />
100→              ))}
101→            </div>
102→          )
103→        ) : (
104→          <>
105→            {messages.length === 0 && (
106→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
107→                Type a prompt to spawn a Claude agent
108→              </div>
109→            )}
110→            {displayItems.map((item) => {
111→              if (item.kind === "condensed") {
112→                return <CondensedToolGroup key={item.id} group={item} />;
113→              }
114→              const msg = item.message;
115→              return msg.userQuestion ? (
116→                <UserQuestion
117→                  key={msg.id}
118→                  message={msg}
119→                  onRespond={onRespondToUserQuestion}
120→                />
121→              ) : msg.controlRequest ? (
122→                <ControlRequest
123→                  key={msg.id}
124→                  message={msg}
125→                  onRespond={onRespondToControl}
126→                />
127→              ) : (
128→                <Message key={msg.id} message={msg} />
129→              );
130→            })}
131→          </>
132→        )}
133→      </div>
134→
135→      <form
136→        onSubmit={handleSubmit}
137→        className="flex gap-2 border-t px-4 py-3"
138→      >
139→        <input
140→          type="text"
141→          value={input}
142→          onChange={(e) => setInput(e.target.value)}
143→          placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
144→          className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
145→        />
146→        <Button type="submit" disabled={!connected || !input.trim()}>
147→          {isActive ? "Send" : "Spawn"}
148→        </Button>
149→      </form>
150→    </div>
151→  );
152→}
