154→/** Badge color per Claude NDJSON message type. */
155→const TYPE_COLORS: Record<string, string> = {
156→  system: "text-yellow-500",
157→  assistant: "text-blue-400",
158→  result: "text-green-500",
159→  control_request: "text-orange-400",
160→  keep_alive: "text-muted-foreground",
161→};
162→
163→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
164→  const [expanded, setExpanded] = useState(false);
165→  const subtype = (message as { subtype?: string }).subtype;
166→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
167→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
168→
169→  return (
170→    <div className="font-mono text-[11px] leading-relaxed">
171→      <button
172→        onClick={() => setExpanded((v) => !v)}
173→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
174→      >
175→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
176→        <span className={colorClass}>{typeLabel}</span>
177→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
178→      </button>
179→      {expanded && (
180→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
181→          {JSON.stringify(message, null, 2)}
182→        </pre>
183→      )}
184→    </div>
185→  );
186→}
