  broadcastAgentList();
  break;
}

case "clear_history": {
  const agent = agents.get(msg.agentId);
  if (!agent) {
    sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
    break;
  }
  agent.messageHistory = [];
  persistAgentSync(agent);
