  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
    sendToBrowser({ type: "error", agentId: msg.agentId, error: "Agent is already running" });
    break;
  }
  relaunchAgent(agent);
  break;
}

case "delete_agent": {
  deleteAgent(msg.agentId);
  break;
}

case "rename_agent": {
  const agent = agents.get(msg.agentId);
  if (!agent) {
    sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
    break;
  }
  agent.label = msg.label;
  persistAgentSync(agent);
  broadcastAgentList();
  break;
}

case "clear_history": {
  const agent = agents.get(msg.agentId);
  if (!agent) {
    sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
    break;
  }
  agent.messageHistory = [];
  persistAgentSync(agent);
  sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
  break;
}
```

Also update the import of `BrowserMessage` at the top of the file -- the type itself is a union, so adding new members to the union in `types.ts` is sufficient; no import change needed.

