  agentOrder: string[];
  activeAgentId: string | null;
  onSelect: (agentId: string | null) => void;
  onNewAgent: () => void;
  onKill: (agentId: string) => void;
  onRelaunch: (agentId: string) => void;
  onDelete: (agentId: string) => void;
  onRename: (agentId: string, label: string) => void;
  onClearHistory: (agentId: string) => void;
}) {
```

#### Context menu state

```typescript
const [contextMenu, setContextMenu] = useState<{
  agentId: string;
  x: number;
  y: number;
} | null>(null);

// For inline rename
const [renamingId, setRenamingId] = useState<string | null>(null);
const [renameValue, setRenameValue] = useState("");
```

#### onContextMenu handler on each agent button

Replace the existing `<button>` for each agent to include:

```typescript
onContextMenu={(e) => {
  e.preventDefault();
  setContextMenu({ agentId: id, x: e.clientX, y: e.clientY });
}}
```

#### Context menu component (inline, rendered at bottom of sidebar)

Render a small positioned `<div>` when `contextMenu` is not null. Use `useEffect` with a click-outside listener to close it. Menu items:

```
Rename          -> setRenamingId(agentId), close menu
Relaunch        -> onRelaunch(agentId), close menu    [show only if status in disconnected/done/error AND agent has a sessionId -- but sessionId is not in AgentInfo, so we key off status only]
Kill            -> onKill(agentId), close menu         [show only if status in spawning/connected/thinking]
Clear History   -> onClearHistory(agentId), close menu
---
Delete          -> window.confirm() then onDelete(agentId), close menu
```

The context menu is a simple `fixed`-position div with Tailwind classes:

```typescript
{contextMenu && (
  <div
    className="fixed z-50 min-w-[160px] rounded-md border bg-popover p-1 shadow-md text-popover-foreground"
    style={{ top: contextMenu.y, left: contextMenu.x }}
  >
    <ContextMenuItem
      label="Rename"
      onClick={() => {
        const agent = agents.get(contextMenu.agentId);
        setRenamingId(contextMenu.agentId);
        setRenameValue(agent?.label ?? "");
        setContextMenu(null);
      }}
    />
    {/* Conditionally show Relaunch */}
    {(() => {
      const agent = agents.get(contextMenu.agentId);
      const canRelaunch = agent && ["disconnected", "done", "error"].includes(agent.status);
      const canKill = agent && ["spawning", "connected", "thinking"].includes(agent.status);
      return (
        <>
          {canRelaunch && (
            <ContextMenuItem label="Relaunch" onClick={() => { onRelaunch(contextMenu.agentId); setContextMenu(null); }} />
          )}
          {canKill && (
            <ContextMenuItem label="Kill" onClick={() => { onKill(contextMenu.agentId); setContextMenu(null); }} />
          )}
        </>
      );
    })()}
    <ContextMenuItem
      label="Clear History"
      onClick={() => { onClearHistory(contextMenu.agentId); setContextMenu(null); }}
    />
    <div className="my-1 h-px bg-border" />
    <ContextMenuItem
      label="Delete"
      destructive
      onClick={() => {
        if (window.confirm("Delete this agent permanently?")) {
          onDelete(contextMenu.agentId);
        }
        setContextMenu(null);
      }}
    />
  </div>
)}
```

Add a small helper component at the bottom of the file:

```typescript
function ContextMenuItem({
  label,
  onClick,
  destructive = false,
}: {
  label: string;
  onClick: () => void;
  destructive?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex w-full items-center rounded-sm px-2 py-1.5 text-xs transition-colors",
        destructive
          ? "text-red-500 hover:bg-red-500/10"
          : "hover:bg-accent"
      )}
    >
      {label}
    </button>
  );
}
```

#### Inline rename mode

When `renamingId` matches the current agent's ID, replace the label `<span>` with an `<input>`:

```typescript
{renamingId === id ? (
  <input
    autoFocus
    value={renameValue}
    onChange={(e) => setRenameValue(e.target.value)}
    onBlur={() => {
      if (renameValue.trim()) onRename(id, renameValue.trim());
      setRenamingId(null);
    }}
    onKeyDown={(e) => {
      if (e.key === "Enter") {
        if (renameValue.trim()) onRename(id, renameValue.trim());
        setRenamingId(null);
      }
      if (e.key === "Escape") setRenamingId(null);
    }}
    className="flex-1 min-w-0 bg-transparent text-xs outline-none border-b border-ring"
  />
) : (
  <span className="truncate">{agent.label || "new agent"}</span>
)}
```

#### Click-outside to dismiss context menu

Add a `useEffect` at the top of the component:

```typescript
useEffect(() => {
  if (!contextMenu) return;
  const handler = () => setContextMenu(null);
  window.addEventListener("click", handler);
  return () => window.removeEventListener("click", handler);
}, [contextMenu]);
```

